{
  "technical_and_design_decisions": [
    "Implement RabbitMQ resource cleanup on the container side via StreamPlugin, triggered by an optional '--clean' flag on 'stream destroy', using RabbitManagementTemplate/RabbitAdmin to check consumer counts and remove queues/bindings/exchanges safely.",
    "Capture module exceptions via Spring Integration error channels; bridge per-module error channels to a stream-level error channel that users can subscribe to.",
    "For security (U3 spike), use Spring Security 6 with Spring Boot 3 auto-configuration to secure REST endpoints; externalize credentials in config files; apply same auth to DSL shell and Admin UI; deliver a prototype and design document rather than full production rollout.",
    "Create a new 'http-mvc' source module based on Spring MVC and embedded Tomcat, reusing existing HTTP module code, adding content-type negotiation and full header mapping.",
    "Propagate status changes using Spring ApplicationEvents published to the message bus from containers to admin, and expose them to UI clients via Server-Sent Events (SSE) with client-side polling fallback.",
    "Implement SFTP source using Spring Integration SFTP inbound adapter with configurable session factory and polling; use embedded Apache Mina SSHD for tests.",
    "Implement ElasticSearch sink using Spring Data Elasticsearch (or REST client) with configurable index and bulk indexing."
  ],
  "assumptions": [
    "Development is done by a single senior Spring developer; effort estimates are pure work-hours excluding meetings and calendar delays.",
    "Base platform is a modern Spring XD/Spring Boot 3.x environment on Java 17+ with existing module extension points.",
    "For U3, only the spike (research, design, prototype, documentation) is in scope, not hardening all REST endpoints for production.",
    "RabbitMQ is the targeted broker for U1; other brokers are out of scope.",
    "Integration testing uses Testcontainers or embedded servers (RabbitMQ, Elasticsearch, SFTP) available in the dev environment.",
    "All required property keys for U4 are discoverable from existing code; documentation will be added in-repo.",
    "No clarifying questions are asked; ambiguous requirements are resolved by the above decisions and assumptions."
  ],
  "activities": [
    {
      "activity_id": "U1-1",
      "activity_name": "Design RabbitMQ cleanup approach",
      "activity_description": "Analyze RabbitAdmin/RabbitManagementTemplate capabilities, decide container-side cleanup via StreamPlugin with --clean flag, handle fanout exchanges and last consumer checks.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U1-2",
      "activity_name": "Implement optional queue/topic cleanup",
      "activity_description": "Code the cleanup logic in StreamPlugin triggered by 'stream destroy --clean', deleting queues/topics/bindings/exchanges when safe.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U1-3",
      "activity_name": "Integration tests for cleanup",
      "activity_description": "Write integration tests using RabbitMQ test container to verify optional cleanup behavior and edge cases (producers/consumers remaining).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U2-1",
      "activity_name": "Design error channel notification architecture",
      "activity_description": "Define per-module error channels and bridging to stream-level user-subscribable error channel using Spring Integration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U2-2",
      "activity_name": "Implement module error capturing and routing",
      "activity_description": "Wire exception handlers in module deployment to publish to error channels and make them accessible to users.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "U2-3",
      "activity_name": "Tests for error channel",
      "activity_description": "Create unit/integration tests verifying exceptions are captured and delivered to the error channel.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U3-1",
      "activity_name": "Research Spring Security/Boot for REST",
      "activity_description": "Investigate OOTB features of Spring Security and Spring Boot relevant to securing XD REST API endpoints.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U3-2",
      "activity_name": "Design security configuration approach",
      "activity_description": "Design credential configuration, DSL shell auth, and Admin UI handling for secured endpoints.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U3-3",
      "activity_name": "Prototype secured REST endpoints",
      "activity_description": "Implement a prototype securing a subset of REST endpoints to validate the design.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "U3-4",
      "activity_name": "Document spike findings and UX",
      "activity_description": "Write up research, design decisions, and recommended developer/user experience.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U4-1",
      "activity_name": "Document xd.* property keys",
      "activity_description": "Identify and document available property keys such as ${xd.stream.name}, ${xd.job.name}, ${xd.container.id} for users.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U5-1",
      "activity_name": "Design MVC-aware HTTP module",
      "activity_description": "Design new http-mvc source module structure with embedded Tomcat, Spring MVC controller, content-type negotiation, and header mapping.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "U5-2",
      "activity_name": "Implement http-mvc source module",
      "activity_description": "Develop the module extending existing HTTP source, adding richer content-type support and full header mapping.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "U5-3",
      "activity_name": "Integration tests for HTTP module",
      "activity_description": "Test the module with embedded Tomcat, verifying content-type and headers, optionally with security.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "U5-4",
      "activity_name": "Update module documentation/examples",
      "activity_description": "Add docs and example stream definitions for the new http-mvc module.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U6-1",
      "activity_name": "Design event propagation and client notification",
      "activity_description": "Design server-side event publishing via message bus and SSE/WebSocket exposure to UI with polling fallback.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U6-2",
      "activity_name": "Implement server-side event publishing/bus propagation",
      "activity_description": "Code containers to emit status change events to admin via bus and admin to track them.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U6-3",
      "activity_name": "Implement client polling/subscription (UI/admin)",
      "activity_description": "Implement client-side polling and SSE subscription in admin UI/clients to receive status updates.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "U6-4",
      "activity_name": "Tests for status change detection",
      "activity_description": "Verify events propagate and clients receive updates correctly.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U7-1",
      "activity_name": "Design SFTP source module",
      "activity_description": "Design SFTP source configuration (session factory, inbound adapter, polling) using Spring Integration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U7-2",
      "activity_name": "Implement SFTP source using Spring Integration",
      "activity_description": "Develop the SFTP source module supporting file transfer and management.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U7-3",
      "activity_name": "Testing infra and integration tests (embedded SFTP)",
      "activity_description": "Set up embedded SSHD server and write integration tests for SFTP module.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U7-4",
      "activity_name": "Documentation for SFTP module",
      "activity_description": "Document configuration options and usage examples.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U8-1",
      "activity_name": "Design ElasticSearch sink module",
      "activity_description": "Design sink module with index mapping, document conversion, and bulk indexing options.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U8-2",
      "activity_name": "Implement ElasticSearch sink",
      "activity_description": "Develop the sink module using Spring Data Elasticsearch or REST client.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U8-3",
      "activity_name": "Integration tests with ES",
      "activity_description": "Test sink against Elasticsearch test container verifying indexing and search.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U8-4",
      "activity_name": "Documentation for ES sink",
      "activity_description": "Document sink configuration and examples.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "INT-1",
      "activity_name": "System integration and end-to-end verification",
      "activity_description": "Merge all features into main codebase, ensure build passes, perform cross-feature smoke tests, and aggregate documentation.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 246
  }
}

